import { useTheme } from "@mui/material/styles";
import { useEffect, useState } from "react";
import ReactApexChart from "react-apexcharts";
import { fetchAnalysisData } from "./index"; // Ensure correct import path

const areaChartOptions = {
  chart: {
    height: 450,
    type: "area",
    toolbar: { show: false },
  },
  dataLabels: { enabled: false },
  stroke: { curve: "smooth", width: 2 },
  grid: { strokeDashArray: 0 },
};

export default function IncomeChart({ chartData }) {
  const theme = useTheme();
  const { primary, secondary } = theme.palette.text;
  const line = theme.palette.divider;

  const [options, setOptions] = useState(areaChartOptions);
  const [series, setSeries] = useState([]);
  const [points, setPoints] = useState([]);

  useEffect(() => {
    if (!chartData) return;

    const loadChartData = async () => {
      try {
        const { startDate, endDate, epochLength, numSurfers, numAnchors, analysisType } = chartData;
        const { points, series } = await fetchAnalysisData(startDate, endDate, epochLength, numSurfers, numAnchors, analysisType);

        if (points && series) {
            setPoints(points);
            setSeries(series.map((dataSet) => ({
              ...dataSet,
              data: dataSet.data.map(value => Math.max(value, 0)), // Ensure no negative values
            })));
          } else {
            console.warn("⚠️ No data received from fetchAnalysisData");
          }
      } catch (error) {
        console.error("❌ Error loading chart data:", error);
      }
    };

    loadChartData();
  }, [chartData]); // Fetch data whenever `chartData` changes

  useEffect(() => {
    setOptions((prevState) => ({
      ...prevState,
      colors: [
        theme.palette.primary.main,
        theme.palette.success.main,
        theme.palette.warning.main,
        theme.palette.error.main,
        theme.palette.info.main,
        "#d303fc", // Purple shade
        "#FF5733", // Orange-Red
        "#33FF57", // Green
        "#5733FF", // Blue
        "#FFC300", // Yellow-Gold
        "#FF33A1", // Pink-Magenta
        "#33FFF3", // Cyan
        "#8D33FF", // Violet
        "#FF8C33", // Deep Orange
        "#33A1FF", // Sky Blue
        "#A1FF33", // Lime Green
        "#B833FF", // Deep Purple
        "#33FF8C", // Mint Green
        "#FF3333", // Bright Red
        "#338CFF", // Ocean Blue
        "#FF338C", // Rose Pink
      ],
      xaxis: {
        categories: points.map((p) =>
          new Date(p).toLocaleString(undefined, { month: "short", day: "2-digit", year: "numeric" })
        ),
        labels: { style: { colors: new Array(points.length).fill(secondary) } },
        axisBorder: { show: true, color: line },
        tickAmount: points.length > 1 ? points.length - 1 : 1,
      },
      yaxis: {
        labels: {
          formatter: (value) => {
            if (typeof value !== "number" || isNaN(value)) {
                return 0;
            }
            if (value < 0) {
                return 0
            }
            if (value >= 1 || value === 0) return value.toFixed(2); // Show 2 decimal places for values >= 1 or exactly 0
            return value.toPrecision(2); // Show small decimal values in full (e.g., 0.35 stays 0.35, 0.008 becomes 0.0080)
          },
        },
      },
      grid: { borderColor: line },
    }));
  }, [theme, points, series, secondary, line]);

  return <ReactApexChart options={options} series={series} type="area" height={450} />;
}
